// Generated by exit-ramp. Key and value encoding for moving Deno KV data onto Workers KV.
//
// Deno KV keys are arrays ("tuples") of parts. Workers KV keys are flat strings (max 512 bytes) that list in
// UTF-8 byte order. This codec maps a tuple to a string so that the string order matches Deno KV's tuple order
// for every part type, and so that "all keys under prefix [a, b]" becomes a plain KV prefix query.
//
// Part order in Deno KV: Uint8Array < string < bigint < number < boolean(false < true).

export type KvKeyPart = Uint8Array | string | number | bigint | boolean;
export type KvKey = readonly KvKeyPart[];

/** Separator between parts. Lower than every character that can appear unescaped in a part. */
export const SEP = "!";
/** Escape lead character. Also lower than every unescaped character, and higher than SEP. */
const ESC = '"';

const TAG_BYTES = "1";
const TAG_STRING = "2";
const TAG_BIGINT = "3";
const TAG_NUMBER = "4";
const TAG_BOOL = "5";

const MAX_KEY_BYTES = 512;

function escapeString(s: string): string {
  let out = "";
  for (const ch of s) {
    const c = ch.codePointAt(0)!;
    out += c <= 0x22 ? ESC + c.toString(16).toUpperCase().padStart(2, "0") : ch;
  }
  return out;
}

function unescapeString(s: string): string {
  let out = "";
  for (let i = 0; i < s.length; i++) {
    if (s[i] === ESC) {
      out += String.fromCharCode(parseInt(s.slice(i + 1, i + 3), 16));
      i += 2;
    } else out += s[i];
  }
  return out;
}

const hex = (b: Uint8Array) => Array.from(b, (x) => x.toString(16).padStart(2, "0")).join("");
function unhex(s: string): Uint8Array {
  const out = new Uint8Array(s.length / 2);
  for (let i = 0; i < out.length; i++) out[i] = parseInt(s.slice(i * 2, i * 2 + 2), 16);
  return out;
}

function encodeNumber(n: number): string {
  const buf = new DataView(new ArrayBuffer(8));
  buf.setFloat64(0, n, false);
  let hi = buf.getUint32(0, false);
  let lo = buf.getUint32(4, false);
  if (hi & 0x80000000) {
    hi = ~hi >>> 0;
    lo = ~lo >>> 0;
  } else {
    hi = (hi | 0x80000000) >>> 0;
  }
  return hi.toString(16).padStart(8, "0") + lo.toString(16).padStart(8, "0");
}

function decodeNumber(s: string): number {
  let hi = parseInt(s.slice(0, 8), 16);
  let lo = parseInt(s.slice(8, 16), 16);
  if (hi & 0x80000000) {
    hi = (hi & 0x7fffffff) >>> 0;
  } else {
    hi = ~hi >>> 0;
    lo = ~lo >>> 0;
  }
  const buf = new DataView(new ArrayBuffer(8));
  buf.setUint32(0, hi, false);
  buf.setUint32(4, lo, false);
  return buf.getFloat64(0, false);
}

function encodeBigint(n: bigint): string {
  const neg = n < 0n;
  const digits = (neg ? -n : n).toString();
  if (digits.length > 9999) throw new RangeError("bigint key part is too large");
  if (!neg) return "1" + String(digits.length).padStart(4, "0") + digits;
  const comp = Array.from(digits, (d) => String(9 - Number(d))).join("");
  return "0" + String(9999 - digits.length).padStart(4, "0") + comp;
}

function decodeBigint(s: string): bigint {
  if (s[0] === "1") return BigInt(s.slice(5));
  const comp = s.slice(5);
  const digits = Array.from(comp, (d) => String(9 - Number(d))).join("");
  return -BigInt(digits);
}

function encodePart(p: KvKeyPart): string {
  if (typeof p === "string") return TAG_STRING + escapeString(p);
  if (typeof p === "number") return TAG_NUMBER + encodeNumber(p);
  if (typeof p === "bigint") return TAG_BIGINT + encodeBigint(p);
  if (typeof p === "boolean") return TAG_BOOL + (p ? "1" : "0");
  if (p instanceof Uint8Array) return TAG_BYTES + hex(p);
  throw new TypeError("Unsupported key part type: " + typeof p);
}

function decodePart(s: string): KvKeyPart {
  const body = s.slice(1);
  switch (s[0]) {
    case TAG_STRING:
      return unescapeString(body);
    case TAG_NUMBER:
      return decodeNumber(body);
    case TAG_BIGINT:
      return decodeBigint(body);
    case TAG_BOOL:
      return body === "1";
    case TAG_BYTES:
      return unhex(body);
    default:
      throw new TypeError("Corrupt key part: " + s);
  }
}

/** Encode a Deno-style key tuple as a Workers KV key. */
export function encodeKey(key: KvKey): string {
  if (key.length === 0) throw new TypeError("Key cannot be empty");
  const s = key.map(encodePart).join(SEP);
  if (new TextEncoder().encode(s).length > MAX_KEY_BYTES) {
    throw new RangeError(`Encoded key is longer than ${MAX_KEY_BYTES} bytes (Workers KV limit). Shorten the key parts.`);
  }
  return s;
}

export function decodeKey(s: string): KvKey {
  return s.split(SEP).map(decodePart);
}

/** KV prefix that matches every key strictly below `prefix` (like Deno's kv.list({ prefix })). [] matches everything. */
export function prefixFor(prefix: KvKey): string {
  return prefix.length === 0 ? "" : prefix.map(encodePart).join(SEP) + SEP;
}

/** Compare two encoded keys in UTF-8 byte order, which is how Workers KV lists keys. */
export function compareEncoded(a: string, b: string): number {
  if (a === b) return 0;
  const ia = a[Symbol.iterator]();
  const ib = b[Symbol.iterator]();
  for (;;) {
    const x = ia.next();
    const y = ib.next();
    if (x.done && y.done) return 0;
    if (x.done) return -1;
    if (y.done) return 1;
    const cx = x.value.codePointAt(0)!;
    const cy = y.value.codePointAt(0)!;
    if (cx !== cy) return cx < cy ? -1 : 1; // code point order equals UTF-8 byte order
  }
}

/* ------------------------------------------------------------------------------------------------ */
/* Values. Deno KV stores structured-clone values. JSON cannot, so these types are tagged.            */
/* ------------------------------------------------------------------------------------------------ */

const TAG = "$exitRamp";

function toBase64(b: Uint8Array): string {
  let s = "";
  for (let i = 0; i < b.length; i += 0x8000) s += String.fromCharCode(...b.subarray(i, i + 0x8000));
  return btoa(s);
}
function fromBase64(s: string): Uint8Array {
  const bin = atob(s);
  const out = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
  return out;
}

function toTagged(v: unknown, seen: WeakSet<object>): unknown {
  if (v === undefined) return { [TAG]: "undefined" };
  if (v === null || typeof v === "string" || typeof v === "boolean") return v;
  if (typeof v === "number") return Number.isFinite(v) && !Object.is(v, -0) ? v : { [TAG]: "number", v: Object.is(v, -0) ? "-0" : String(v) };
  if (typeof v === "bigint") return { [TAG]: "bigint", v: v.toString() };
  if (typeof v === "function" || typeof v === "symbol") throw new TypeError("Cannot store a " + typeof v);
  const o = v as object;
  if (seen.has(o)) throw new TypeError("Circular values are not supported by the Workers KV adapter");
  if (v instanceof Date) return { [TAG]: "date", v: v.toISOString() };
  if (v instanceof Uint8Array) return { [TAG]: "bytes", v: toBase64(v) };
  if (v instanceof ArrayBuffer) return { [TAG]: "arraybuffer", v: toBase64(new Uint8Array(v)) };
  if (v instanceof RegExp) return { [TAG]: "regexp", source: v.source, flags: v.flags };
  seen.add(o);
  try {
    if (v instanceof Map) return { [TAG]: "map", v: Array.from(v, ([k, x]) => [toTagged(k, seen), toTagged(x, seen)]) };
    if (v instanceof Set) return { [TAG]: "set", v: Array.from(v, (x) => toTagged(x, seen)) };
    if (Array.isArray(v)) return v.map((x) => toTagged(x, seen));
    const out: Record<string, unknown> = {};
    for (const [k, x] of Object.entries(v as Record<string, unknown>)) out[k] = toTagged(x, seen);
    return TAG in out ? { [TAG]: "object", v: out } : out;
  } finally {
    seen.delete(o);
  }
}

function fromTagged(v: unknown): unknown {
  if (v === null || typeof v !== "object") return v;
  if (Array.isArray(v)) return v.map(fromTagged);
  const o = v as Record<string, any>;
  if (TAG in o) {
    switch (o[TAG]) {
      case "undefined":
        return undefined;
      case "number":
        return o.v === "-0" ? -0 : Number(o.v);
      case "bigint":
        return BigInt(o.v);
      case "date":
        return new Date(o.v);
      case "bytes":
        return fromBase64(o.v);
      case "arraybuffer":
        return fromBase64(o.v).buffer;
      case "regexp":
        return new RegExp(o.source, o.flags);
      case "map":
        return new Map((o.v as [unknown, unknown][]).map(([k, x]) => [fromTagged(k), fromTagged(x)]));
      case "set":
        return new Set((o.v as unknown[]).map(fromTagged));
      case "object":
        return Object.fromEntries(Object.entries(o.v as Record<string, unknown>).map(([k, x]) => [k, fromTagged(x)]));
    }
  }
  return Object.fromEntries(Object.entries(o).map(([k, x]) => [k, fromTagged(x)]));
}

export function serialize(value: unknown): string {
  return JSON.stringify(toTagged(value, new WeakSet()));
}

export function deserialize<T = unknown>(text: string): T {
  return fromTagged(JSON.parse(text)) as T;
}

/** Shape of one item for `wrangler kv bulk put`. */
export interface BulkItem {
  key: string;
  value: string;
  expiration_ttl?: number;
}

/** Turn Deno KV entries into a `wrangler kv bulk put` file body (used by migrate/deno-kv-export.ts). */
export function toBulk(entries: Iterable<{ key: KvKey; value: unknown }>): BulkItem[] {
  const out: BulkItem[] = [];
  for (const e of entries) out.push({ key: encodeKey(e.key), value: serialize(e.value) });
  return out;
}
